# optiplex-gitea-restore: body of the script. The header (STATE_DIR, DATA_DIR, GITEA_USER) is
# generated by machines/optiplex/services/gitea.nix, which also runs shellcheck on the whole.

usage() {
  cat <<'USAGE'
optiplex-gitea-restore: copy the files of the Docker Gitea into /state/gitea (Cutover, restoreMode).

  optiplex-gitea-restore <gitea_data volume directory>
  optiplex-gitea-restore --help

The argument is the `_data` directory of the copied gitea_data volume, the one that holds `git/`
and `gitea/` (/mnt/tbssd/docker/volumes/gitea_data/_data on the Data disk). Run as root, after
optiplex-db-restore has loaded the `gitea` database, with Gitea still switched off
(nixosConfigurations.optiplex-restore). The volume itself is only read.

What it copies (the module layout of services.gitea with stateDir /state/gitea):
  git/repositories/                                   -> /state/gitea/repositories/
  git/lfs/                                            -> /state/gitea/data/lfs/
  gitea/{packages,attachments,avatars,repo-avatars,
         actions_log,home}/                           -> /state/gitea/data/<same>/
Not copied, on purpose:
  gitea/{sessions,indexers,queues,tmp,repo-archive}   rebuilt by Gitea (users log in again)
  gitea/conf/app.ini                                  generated from the Nix config
  gitea/jwt/ and ssh/                                 come from sops (carried keys)
  git/.ssh/                                           the built-in SSH server needs no authorized_keys,
                                                      and the file would make the start rewrite it
Then it chowns /state/gitea to gitea:gitea (mode 0750 for the tree, files keep their execute bits).

It refuses to run when gitea.service is active, when /state is not mounted, or when
/state/gitea/repositories already holds anything (one shot: never merge into a used tree).

Afterwards: the normal deploy (nixos-rebuild --flake .#optiplex). The start runs `gitea migrate`
(schema 331 -> 28.x) and regenerates every hook. Then, as the runbook says:
  optiplex-gitea doctor check --all
  optiplex-gitea admin ...   (and the cleanup_packages cron once, see the ticket)
USAGE
}

die() {
  echo "optiplex-gitea-restore: $*" >&2
  exit 1
}
log() { echo ">> $*"; }

case "${1:-}" in
  -h | --help)
    usage
    exit 0
    ;;
  "") usage >&2; exit 2 ;;
esac
src="${1%/}"
[ $# -eq 1 ] || die "exactly one argument: the volume directory"

[ "$(id -u)" = 0 ] || die "run as root"
[ -d "$src/git/repositories" ] && [ -d "$src/gitea" ] ||
  die "$src does not look like the gitea_data volume (no git/repositories and gitea/)"
mountpoint -q /state || die "/state is not mounted (Data disk missing)"
id "$GITEA_USER" > /dev/null 2>&1 || die "user $GITEA_USER does not exist"
if systemctl is-active --quiet gitea.service; then
  die "gitea.service is active: restore before the first start"
fi
if [ -n "$(ls -A "$STATE_DIR/repositories" 2> /dev/null)" ]; then
  die "$STATE_DIR/repositories is not empty: this is a one-shot restore, never merge"
fi

install -d -m 0750 -o "$GITEA_USER" -g "$GITEA_USER" "$STATE_DIR" "$DATA_DIR"

copy() { # copy <source dir relative to the volume> <destination>
  local from="$src/$1" to="$2"
  if [ ! -d "$from" ]; then
    log "skip $1 (not in the volume)"
    return 0
  fi
  install -d "$to"
  rsync -aH --numeric-ids "$from/" "$to/"
  log "copied $1 ($(du -sh "$to" | cut -f1))"
}

copy git/repositories "$STATE_DIR/repositories"
copy git/lfs "$DATA_DIR/lfs"
for d in packages attachments avatars repo-avatars actions_log home; do
  copy "gitea/$d" "$DATA_DIR/$d"
done

chown -R "$GITEA_USER:$GITEA_USER" "$STATE_DIR"
chmod -R u+rwX,g+rX,g-w,o-rwx "$STATE_DIR"
log "ownership fixed: everything under $STATE_DIR is $GITEA_USER:$GITEA_USER"

n_repos="$(find "$STATE_DIR/repositories" -mindepth 2 -maxdepth 2 -name '*.git' -type d | wc -l)"
log "$n_repos repositories restored"
log "done. Next: the normal deploy; then optiplex-gitea doctor check --all"
